"use client";

import { useCallback, useRef, useState } from "react";

const STATUS = {
  IDLE: "idle",
  READY: "ready",
  WORKING: "working",
  DONE: "done",
  ERROR: "error",
};

const CONFIDENCE_STYLES = {
  high: "bg-success-soft text-success",
  medium: "bg-amber-soft text-amber",
  low: "bg-danger-soft text-danger",
};

export default function Page() {
  const [status, setStatus] = useState(STATUS.IDLE);
  const [file, setFile] = useState(null);
  const [previewUrl, setPreviewUrl] = useState(null);
  const [result, setResult] = useState(null);
  const [errorMessage, setErrorMessage] = useState("");
  const [dragActive, setDragActive] = useState(false);
  const inputRef = useRef(null);

  const acceptFile = useCallback((f) => {
    if (!f || !f.type.startsWith("image/")) return;
    setFile(f);
    setPreviewUrl(URL.createObjectURL(f));
    setResult(null);
    setErrorMessage("");
    setStatus(STATUS.READY);
  }, []);

  const handleDrop = useCallback(
    (e) => {
      e.preventDefault();
      setDragActive(false);
      const f = e.dataTransfer.files?.[0];
      acceptFile(f);
    },
    [acceptFile]
  );

  const handleAnalyze = async () => {
    if (!file) return;
    setStatus(STATUS.WORKING);
    setErrorMessage("");

    try {
      const formData = new FormData();
      formData.append("image", file);

      const res = await fetch("/api/predict", {
        method: "POST",
        body: formData,
      });

      if (!res.ok) throw new Error("lookup_failed");

      const data = await res.json();
      setResult(data);
      setStatus(STATUS.DONE);
    } catch (err) {
      setErrorMessage("Analysis failed. Please try again in a moment.");
      setStatus(STATUS.ERROR);
    }
  };

  const reset = () => {
    setFile(null);
    setPreviewUrl(null);
    setResult(null);
    setErrorMessage("");
    setStatus(STATUS.IDLE);
    if (inputRef.current) inputRef.current.value = "";
  };

  return (
    <main className="min-h-screen bg-canvas">
      {/* Top bar */}
      <header className="border-b border-border bg-surface/80 backdrop-blur">
        <div className="max-w-4xl mx-auto px-6 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2.5">
            <div className="w-8 h-8 rounded-lg bg-brand flex items-center justify-center">
              <SparkIcon className="w-4.5 h-4.5 text-white" />
            </div>
            <span className="font-semibold text-[15px] text-ink">
              Image Insight
            </span>
          </div>
          <span className="text-xs text-ink-faint hidden sm:block">
            AI-powered image analysis
          </span>
        </div>
      </header>

      <div className="max-w-4xl mx-auto px-6 py-14">
        {/* Hero */}
        <div className="mb-10 text-center max-w-lg mx-auto">
          <h1 className="text-3xl sm:text-[2.25rem] font-semibold text-ink tracking-tight leading-tight">
            Analyze any image in seconds
          </h1>
          <p className="mt-3 text-[15px] text-ink-soft leading-relaxed">
            Upload an image to get an instant name, category, and key
            properties — generated automatically, no setup required.
          </p>
        </div>

        {/* Main card */}
        <div className="bg-surface border border-border rounded-2xl shadow-card overflow-hidden">
          <div className="grid md:grid-cols-2">
            {/* Left: upload */}
            <div className="p-6 sm:p-8 md:border-r border-border">
              <div
                onDragOver={(e) => {
                  e.preventDefault();
                  setDragActive(true);
                }}
                onDragLeave={() => setDragActive(false)}
                onDrop={handleDrop}
                onClick={() => inputRef.current?.click()}
                className={`relative aspect-[4/3] w-full rounded-xl cursor-pointer
                  flex items-center justify-center overflow-hidden transition-all
                  ${
                    previewUrl
                      ? "border border-border"
                      : dragActive
                      ? "border-2 border-brand bg-brand-soft"
                      : "border-2 border-dashed border-border hover:border-ink-faint bg-canvas"
                  }`}
              >
                {previewUrl ? (
                  <>
                    {/* eslint-disable-next-line @next/next/no-img-element */}
                    <img
                      src={previewUrl}
                      alt="Selected upload"
                      className="w-full h-full object-cover"
                    />
                    {status === STATUS.WORKING && (
                      <div className="absolute inset-0 bg-ink/50 backdrop-blur-[2px] flex flex-col items-center justify-center gap-2.5">
                        <SpinnerIcon className="w-6 h-6 text-white animate-spin-slow" />
                        <span className="text-xs font-medium text-white">
                          Analyzing…
                        </span>
                      </div>
                    )}
                  </>
                ) : (
                  <div className="flex flex-col items-center gap-3 px-6 text-center">
                    <div className="w-11 h-11 rounded-full bg-surface border border-border flex items-center justify-center">
                      <UploadIcon className="w-5 h-5 text-ink-soft" />
                    </div>
                    <div>
                      <p className="text-sm font-medium text-ink">
                        Drop an image here
                      </p>
                      <p className="text-xs text-ink-faint mt-0.5">
                        or click to browse · PNG, JPG up to 10MB
                      </p>
                    </div>
                  </div>
                )}

                <input
                  ref={inputRef}
                  type="file"
                  accept="image/*"
                  className="hidden"
                  onChange={(e) => acceptFile(e.target.files?.[0])}
                />
              </div>

              {file && (
                <div className="mt-4 flex items-center gap-2 text-xs text-ink-soft animate-fade-up">
                  <FileIcon className="w-3.5 h-3.5 shrink-0 text-ink-faint" />
                  <span className="truncate">{file.name}</span>
                </div>
              )}

              <div className="mt-6 flex gap-3">
                {status !== STATUS.DONE ? (
                  <button
                    onClick={handleAnalyze}
                    disabled={!file || status === STATUS.WORKING}
                    className="inline-flex items-center gap-2 text-sm font-medium px-4 py-2.5 rounded-lg
                      bg-brand text-white shadow-floating
                      disabled:opacity-40 disabled:shadow-none disabled:cursor-not-allowed
                      hover:bg-brand-dark transition-colors"
                  >
                    {status === STATUS.WORKING ? (
                      <>
                        <SpinnerIcon className="w-4 h-4 animate-spin-slow" />
                        Analyzing
                      </>
                    ) : (
                      <>
                        <SparkIcon className="w-4 h-4" />
                        Analyze image
                      </>
                    )}
                  </button>
                ) : (
                  <button
                    onClick={reset}
                    className="inline-flex items-center gap-2 text-sm font-medium px-4 py-2.5 rounded-lg
                      border border-border text-ink hover:bg-canvas transition-colors"
                  >
                    <RefreshIcon className="w-4 h-4" />
                    Analyze another
                  </button>
                )}
              </div>

              {status === STATUS.ERROR && (
                <p className="mt-3 text-xs text-danger flex items-center gap-1.5 animate-fade-up">
                  <AlertIcon className="w-3.5 h-3.5 shrink-0" />
                  {errorMessage}
                </p>
              )}
            </div>

            {/* Right: results */}
            <div className="p-6 sm:p-8 bg-canvas/40 flex flex-col">
              {status === STATUS.WORKING && <ResultSkeleton />}

              {status === STATUS.DONE && result && (
                <div className="flex flex-col gap-5 animate-fade-up">
                  <div>
                    <span className="text-[11px] font-medium uppercase tracking-wide text-ink-faint">
                      Identified as
                    </span>
                    <div className="flex items-center gap-2 mt-1">
                      <h2 className="text-xl font-semibold text-ink">
                        {result.name || "Unknown"}
                      </h2>
                      {result.identified === false && (
                        <span className="text-[10px] font-medium uppercase tracking-wide px-1.5 py-0.5 rounded bg-danger-soft text-danger">
                          Low match
                        </span>
                      )}
                    </div>
                  </div>

                  <div className="flex flex-wrap gap-2">
                    <Badge label={result.classification || "Unclassified"} />
                    <span
                      className={`inline-flex items-center text-xs font-medium px-2.5 py-1 rounded-full ${
                        CONFIDENCE_STYLES[result.confidence] ||
                        CONFIDENCE_STYLES.low
                      }`}
                    >
                      {(result.confidence || "low")
                        .charAt(0)
                        .toUpperCase() +
                        (result.confidence || "low").slice(1)}{" "}
                      confidence
                    </span>
                  </div>

                  {result.properties && result.properties.length > 0 && (
                    <div>
                      <span className="text-[11px] font-medium uppercase tracking-wide text-ink-faint">
                        Key properties
                      </span>
                      <ul className="mt-2 flex flex-col gap-1.5">
                        {result.properties.map((p, i) => (
                          <li
                            key={i}
                            className="flex items-start gap-2 text-sm text-ink"
                          >
                            <CheckIcon className="w-3.5 h-3.5 mt-0.5 shrink-0 text-brand" />
                            <span>{p}</span>
                          </li>
                        ))}
                      </ul>
                    </div>
                  )}

                  {result.note && (
                    <p className="text-xs text-ink-faint border-t border-border pt-3">
                      {result.note}
                    </p>
                  )}
                </div>
              )}

              {status !== STATUS.WORKING &&
                !(status === STATUS.DONE && result) && (
                  <div className="flex-1 flex flex-col items-center justify-center text-center py-8">
                    <div className="w-10 h-10 rounded-full bg-surface border border-border flex items-center justify-center mb-3">
                      <ScanIcon className="w-5 h-5 text-ink-faint" />
                    </div>
                    <p className="text-sm text-ink-soft">
                      Results will appear here
                    </p>
                    <p className="text-xs text-ink-faint mt-1 max-w-[220px]">
                      Upload an image and click analyze to get started
                    </p>
                  </div>
                )}
            </div>
          </div>
        </div>

        <p className="text-xs text-ink-faint text-center mt-6">
          Predictions are inferred from the file name and may not always be
          accurate.
        </p>
      </div>
    </main>
  );
}

function Badge({ label }) {
  return (
    <span className="inline-flex items-center text-xs font-medium px-2.5 py-1 rounded-full bg-brand-soft text-brand">
      {label}
    </span>
  );
}

function ResultSkeleton() {
  return (
    <div className="flex flex-col gap-5">
      <div>
        <div className="h-2.5 w-20 rounded shimmer" />
        <div className="h-5 w-40 rounded shimmer mt-2.5" />
      </div>
      <div className="flex gap-2">
        <div className="h-6 w-24 rounded-full shimmer" />
        <div className="h-6 w-28 rounded-full shimmer" />
      </div>
      <div className="flex flex-col gap-2">
        <div className="h-2.5 w-24 rounded shimmer" />
        <div className="h-3.5 w-full rounded shimmer mt-1" />
        <div className="h-3.5 w-5/6 rounded shimmer" />
        <div className="h-3.5 w-2/3 rounded shimmer" />
      </div>
    </div>
  );
}

